<?php
defined( 'ABSPATH' ) || exit;
const MORGENBROT_DEMO_OPTION = 'morgenbrot_demo_manifest_v2';
function morgenbrot_demo_admin_menu(){add_menu_page('Morgenbrot','Morgenbrot','manage_options','morgenbrot','morgenbrot_demo_page','dashicons-store',58);add_submenu_page('morgenbrot','Demo-Inhalte installieren','Demo-Inhalte installieren','manage_options','morgenbrot','morgenbrot_demo_page');}
add_action('admin_menu','morgenbrot_demo_admin_menu');
function morgenbrot_demo_page(){if(!current_user_can('manage_options'))return;$message='';if(isset($_POST['morgenbrot_install_demo'])&&check_admin_referer('morgenbrot_install_demo')){$stats=morgenbrot_install_demo();$message=sprintf('Demo-Inhalte installiert/aktualisiert: %d Einträge.',$stats);}if(isset($_POST['morgenbrot_remove_demo'])&&check_admin_referer('morgenbrot_remove_demo')&&isset($_POST['confirm_remove'])){$stats=morgenbrot_remove_demo();$message=sprintf('Nur vom Demo-Installer erstellte Inhalte entfernt: %d Einträge.',$stats);}echo'<div class="wrap"><h1>Morgenbrot → Demo-Inhalte installieren</h1>';if($message)echo'<div class="notice notice-success"><p>'.esc_html($message).'</p></div>';echo'<p>Der Installer ist idempotent und aktualisiert ausschließlich eindeutig markierte Demo-Inhalte.</p><form method="post">';wp_nonce_field('morgenbrot_install_demo');echo'<button class="button button-primary" name="morgenbrot_install_demo" value="1">Demo-Inhalte installieren/aktualisieren</button></form><hr><h2>Demo-Inhalte entfernen</h2><p>Benutzerinhalte werden nicht gelöscht. Entfernt werden nur IDs im geschützten Demo-Manifest.</p><form method="post">';wp_nonce_field('morgenbrot_remove_demo');echo'<label><input type="checkbox" name="confirm_remove" value="1" required> Ich bestätige die Entfernung der Demo-Inhalte.</label><p><button class="button button-secondary" name="morgenbrot_remove_demo" value="1" onclick="return confirm(\'Demo-Inhalte wirklich entfernen?\')">Demo-Inhalte entfernen</button></p></form></div>';}
function morgenbrot_demo_post($type,$key,$title,$args=array()){ $found=get_posts(array('post_type'=>$type,'post_status'=>'any','numberposts'=>1,'meta_key'=>'_morgenbrot_demo_key','meta_value'=>$key));$created=false;if($found)$id=$found[0]->ID;else{$id=wp_insert_post(array_merge(array('post_type'=>$type,'post_status'=>'publish','post_title'=>$title),$args));$created=true;}if($id&&!is_wp_error($id)){wp_update_post(array_merge(array('ID'=>$id,'post_title'=>$title),$args));update_post_meta($id,'_morgenbrot_demo_key',$key);}return array((int)$id,$created);}
function morgenbrot_demo_term($taxonomy,$name){$term=term_exists($name,$taxonomy);$created=false;if(!$term){$term=wp_insert_term($name,$taxonomy);$created=true;}return array((int)(is_array($term)?$term['term_id']:$term),$created);}
function morgenbrot_install_demo(){
	$manifest=get_option(MORGENBROT_DEMO_OPTION,array('posts'=>array(),'terms'=>array(),'menu'=>0));$count=0;$term_ids=array();foreach(array('Brot','Brötchen','Gebäck','Kuchen','Snacks','Getränke')as$name){[$id,$new]=morgenbrot_demo_term('bakery_product_category',$name);$term_ids['category'][$name]=$id;if($new)$manifest['terms'][]=array('id'=>$id,'taxonomy'=>'bakery_product_category');}foreach(array('Glutenhaltiges Getreide','Eier','Milch','Schalenfrüchte','Sesam','Soja')as$name){[$id,$new]=morgenbrot_demo_term('bakery_allergen',$name);$term_ids['allergen'][$name]=$id;if($new)$manifest['terms'][]=array('id'=>$id,'taxonomy'=>'bakery_allergen');}
	$products=array(
		array('sauerteig','Morgenbrot Sauerteig','MB-1001','Brot',4.80,0,'750 g','Roggenmehl, Weizenmehl, Wasser, Salz',array('Glutenhaltiges Getreide'),1,1),array('dinkel','Dinkelvollkornbrot','MB-1002','Brot',5.20,4.60,'750 g','Dinkelvollkornmehl, Wasser, Salz, Saaten',array('Glutenhaltiges Getreide','Sesam'),1,1),array('bauernbrot','Bauernbrot','MB-1003','Brot',4.40,0,'750 g','Roggenmehl, Weizenmehl, Sauerteig, Salz',array('Glutenhaltiges Getreide'),1,1),array('klassisch','Klassisches Brötchen','MB-2001','Brötchen',0.55,0,'70 g','Weizenmehl, Wasser, Hefe, Salz',array('Glutenhaltiges Getreide'),1,0),array('koerner','Körnerbrötchen','MB-2002','Brötchen',0.95,0,'85 g','Dinkelmehl, Sonnenblumenkerne, Sesam',array('Glutenhaltiges Getreide','Sesam'),1,0),array('lauge','Laugenbrötchen','MB-2003','Brötchen',0.90,0,'85 g','Weizenmehl, Wasser, Hefe, Salz',array('Glutenhaltiges Getreide'),1,0),array('croissant','Buttercroissant','MB-3001','Gebäck',1.90,0,'85 g','Weizenmehl, Butter, Milch, Eier',array('Glutenhaltiges Getreide','Milch','Eier'),0,0),array('apfeltasche','Apfeltasche','MB-3002','Gebäck',2.40,0,'120 g','Blätterteig, Äpfel, Zimt',array('Glutenhaltiges Getreide','Milch'),0,1),array('apfelkuchen','Apfelkuchen','MB-4001','Kuchen',3.20,0,'Stück','Äpfel, Weizenmehl, Butter, Eier',array('Glutenhaltiges Getreide','Milch','Eier'),0,1),array('kaesekuchen','Käsekuchen','MB-4002','Kuchen',3.40,2.90,'Stück','Quark, Eier, Butter, Weizenmehl',array('Glutenhaltiges Getreide','Milch','Eier'),0,0),array('kaeselauge','Käse-Laugenstange','MB-5001','Snacks',2.80,0,'140 g','Weizenmehl, Käse, Butter',array('Glutenhaltiges Getreide','Milch'),0,0),array('kaffee','Filterkaffee','MB-6001','Getränke',2.20,0,'Becher','Kaffee, Wasser',array(),1,0)
	);foreach($products as$i=>$p){[$id,$new]=morgenbrot_demo_post('bakery_product','product_'.$p[0],$p[1],array('post_excerpt'=>'Mit Sorgfalt in unserer fiktiven Backstube hergestellt.','post_content'=>'Dieses Demonstrationsprodukt verbindet eine handwerklich inspirierte Rezeptur mit klaren Informationen zu Zutaten und Eigenschaften.'));if($new)$manifest['posts'][]=$id;wp_set_object_terms($id,$p[3],'bakery_product_category');wp_set_object_terms($id,$p[8],'bakery_allergen');$meta=array('sku'=>$p[2],'price'=>number_format($p[4],2,'.',''),'sale_price'=>$p[5]?number_format($p[5],2,'.',''):'','price_unit'=>'pro Stück','weight'=>$p[6],'ingredients'=>$p[7],'availability'=>'Täglich, solange der Demo-Vorrat reicht','stock_quantity'=>40-$i,'availability_status'=>$i===11?'limited':'in_stock','vegan'=>$p[9]?'1':'','vegetarian'=>'1','seasonal'=>$p[10]?'1':'','featured'=>$i<4?'1':'');foreach($meta as$k=>$v)update_post_meta($id,'_morgenbrot_'.$k,$v);$count++;}
	$locations=array(array('achern','Filiale Achern Zentrum','Demo-Marktplatz 1','77855','Achern',48.6309,8.0738),array('oberachern','Filiale Oberachern','Fiktiver Mühlenweg 7','77855','Achern-Oberachern',48.6157,8.0795),array('ortenau','Filiale Ortenau Stadt','Demo-Park 3','77876','Kappelrodeck',48.5912,8.1167));foreach($locations as$i=>$l){[$id,$new]=morgenbrot_demo_post('bakery_location','location_'.$l[0],$l[1],array('post_excerpt'=>'Eindeutig fiktiver Standort für das Morgenbrot-Portfolio.','post_content'=>'Diese Filiale und alle Kontaktdaten sind reine Demonstrationsdaten. Sie gehört zu keinem realen Unternehmen.'));if($new)$manifest['posts'][]=$id;$meta=array('street'=>$l[2],'postal_code'=>$l[3],'city'=>$l[4],'phone'=>'+49 7841 00000'.($i+1),'email'=>'filiale'.($i+1).'@morgenbrot.example','latitude'=>(string)$l[5],'longitude'=>(string)$l[6],'hours_monday'=>'06:00-12:00, 13:00-18:00','hours_tuesday'=>'06:00-12:00, 13:00-18:00','hours_wednesday'=>'06:00-18:00','hours_thursday'=>'06:00-18:00','hours_friday'=>'06:00-18:00','hours_saturday'=>'06:00-14:00','hours_sunday'=>$i===0?'08:00-12:00':'','parking'=>'1','accessible'=>'1','services'=>'Vorbestellung, Heißgetränke, Sitzplätze','temporarily_closed'=>'');foreach($meta as$k=>$v)update_post_meta($id,'_morgenbrot_'.$k,$v);$count++;}
	foreach(array('herbstbrot'=>'Unser Herbstbrot ist da','fruehstueck'=>'Sonntagsfrühstück bei Morgenbrot','feiertage'=>'Hinweise zu Feiertagsöffnungszeiten')as$key=>$title){[$id,$new]=morgenbrot_demo_post('post','news_'.$key,$title,array('post_excerpt'=>'Neuigkeiten aus dem fiktiven Morgenbrot-Projekt.','post_content'=>'Dieser Beitrag ist ein redaktioneller Demonstrationstext. Angaben zu Sortiment und Öffnungszeiten sind nicht real.'));if($new)$manifest['posts'][]=$id;$count++;}
	$pages=array('start'=>'Startseite','sortiment'=>'Sortiment','filialen'=>'Filialen','about'=>'Über uns','news'=>'Aktuelles','preorder'=>'Vorbestellen','contact'=>'Kontakt','imprint'=>'Impressum','privacy'=>'Datenschutz');$page_ids=array();foreach($pages as$key=>$title){$content='';if('about'===$key)$content='<p>Wir verbinden klassische Backideen mit einem modernen Blick auf Zutaten, Zugänglichkeit und lokale Nähe. Morgenbrot ist ein fiktives Portfolio-Projekt.</p>';if('preorder'===$key)$content='[morgenbrot_preorder]';if('contact'===$key)$content='[morgenbrot_contact]';if(in_array($key,array('imprint','privacy'),true))$content='<p>Dies ist ein fiktives Portfolio-Projekt und keine geschäftlich betriebene Website. Die dargestellten Unternehmens- und Kontaktdaten dienen ausschließlich Demonstrationszwecken.</p>';[$id,$new]=morgenbrot_demo_post('page','page_'.$key,$title,array('post_content'=>$content));if($new)$manifest['posts'][]=$id;$page_ids[$key]=$id;$count++;}update_option('show_on_front','page');update_option('page_on_front',$page_ids['start']);update_option('page_for_posts',$page_ids['news']);
	$menu=wp_get_nav_menu_object('Morgenbrot Hauptmenü');if(!$menu){$menu_id=wp_create_nav_menu('Morgenbrot Hauptmenü');$manifest['menu']=$menu_id;}else$menu_id=$menu->term_id;$desired=array(array('Startseite',get_permalink($page_ids['start'])),array('Sortiment',get_post_type_archive_link('bakery_product')),array('Filialen',get_post_type_archive_link('bakery_location')),array('Über uns',get_permalink($page_ids['about'])),array('Aktuelles',get_permalink($page_ids['news'])),array('Kontakt',get_permalink($page_ids['contact'])));foreach((array)wp_get_nav_menu_items($menu_id)as$item)if(get_post_meta($item->ID,'_morgenbrot_demo_menu_item',true))wp_delete_post($item->ID,true);foreach($desired as$item){$item_id=wp_update_nav_menu_item($menu_id,0,array('menu-item-title'=>$item[0],'menu-item-url'=>$item[1],'menu-item-type'=>'custom','menu-item-status'=>'publish'));update_post_meta($item_id,'_morgenbrot_demo_menu_item','1');}$locations=get_theme_mod('nav_menu_locations',array());$locations['primary']=$menu_id;$locations['footer']=$menu_id;set_theme_mod('nav_menu_locations',$locations);$manifest['posts']=array_values(array_unique(array_map('absint',$manifest['posts'])));update_option(MORGENBROT_DEMO_OPTION,$manifest,false);flush_rewrite_rules();return$count;
}
function morgenbrot_remove_demo(){
	if(!current_user_can('manage_options'))return 0;
	$manifest=get_option(MORGENBROT_DEMO_OPTION,array());$count=0;$post_ids=array_map('absint',(array)($manifest['posts']??array()));
	if(in_array((int)get_option('page_on_front'),$post_ids,true)){update_option('page_on_front',0);update_option('show_on_front','posts');}
	if(in_array((int)get_option('page_for_posts'),$post_ids,true))update_option('page_for_posts',0);
	foreach($post_ids as$id){if(get_post_meta($id,'_morgenbrot_demo_key',true)){wp_delete_post($id,true);$count++;}}
	foreach((array)($manifest['terms']??array())as$term){if(term_exists((int)$term['id'],$term['taxonomy'])){wp_delete_term((int)$term['id'],$term['taxonomy']);$count++;}}
	if(!empty($manifest['menu'])){wp_delete_nav_menu((int)$manifest['menu']);$count++;}
	delete_option(MORGENBROT_DEMO_OPTION);flush_rewrite_rules();return$count;
}
